 private void refreshSaved(){if(draft==null||draft.nap==null||!route.isEmpty()||SystemClock.elapsedRealtime()-lastRefresh<3000)return;lastRefresh=SystemClock.elapsedRealtime();try(Store store=Records.open(this)){Alarm current=store.alarm(draft.id);if(current==null){if(draft.nap.phase==NapPlan.Phase.CLAIMED||draft.nap.phase==NapPlan.Phase.FINISHED){closeTone();draft=new Alarm(0);draft.smartWindow=0;if(exactSeconds>0)minutes=20;exactSeconds=0;timerRequest=false;timerMessage="";power=false;powerWindow=15;error="Nap completed and removed.";render();}return;}if(current.nap!=null&&(!current.nap.nonce.equals(draft.nap.nonce)||current.nap.phase!=draft.nap.phase||current.enabled!=draft.enabled||!current.nap.error.equals(draft.nap.error))){closeTone();draft=current;readPlan(current.nap);render();}}catch(RuntimeException failure){error="Saved nap status could not be refreshed.";if(problem!=null){problem.setText(error);problem.setVisibility(View.VISIBLE);}}}
 private void updateTimes(){if(draft==null)return;if(motionStatus!=null)motionStatus.setText(motionNotice());NapPlan.Clock clock=Naps.clock(this);long end=pending()||claimed()?draft.nap.projectedDeadline(clock):(startAt>0?startAt:clock.wall())+durationMillis();if(ends!=null){ZoneId zone=ZoneId.systemDefault();String ending=pending()||exactSeconds>0?RecordUi.preciseClock(this,end,zone):RecordUi.clock(this,end,zone);if(exactSeconds>0&&!Instant.ofEpochMilli(end).atZone(zone).toLocalDate().equals(Instant.ofEpochMilli(clock.wall()).atZone(zone).toLocalDate()))ending=Instant.ofEpochMilli(end).atZone(zone).format(DateTimeFormatter.ofPattern("d MMM · ",Locale.getDefault()))+ending;ends.setText(ending);}if(countdown!=null){NapPlan p=draft.nap;String text=p.phase==NapPlan.Phase.PENDING&&draft.enabled?(p.startsIn(clock)>0?"Starts in "+remainingLabel(p.startsIn(clock)):p.power()&&p.minimumRemaining(clock)>0?"Minimum rest remaining · "+RecordUi.duration(p.minimumRemaining(clock)):(p.power()?"Latest wake in · ":"Time remaining · ")+remainingLabel(Math.max(0,p.remaining(clock)))):p.phase==NapPlan.Phase.CLAIMED?"Nap ended":p.phase==NapPlan.Phase.FINISHED?"Nap completed":"Nap cancelled";countdown.setText(text);}}
