 private void loadWave(){if(draft.tone.equals(waveTone))return;String selected=draft.tone;waveTone=selected;waveform=null;if(selected.startsWith("content:")||selected.equals("system"))return;Context app=getApplicationContext();WaveSource loader=waveSource;worker.execute(()->{ToneWaveform result=null;try{result=loader.load(app,selected);}catch(java.io.IOException|RuntimeException ignored){}ToneWaveform value=result;handler.post(()->{if(!isDestroyed()&&waveTone.equals(selected)&&value!=null){waveform=value;if(route.isEmpty())updateWave();}});});}
