 private void remove(){open(()->{Dialog confirm=new Dialog(this);confirm.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout box=Design.col(this);Design.pad(box,22,20);box.setBackground(Design.shape(this,Design.CREAM,22));Design.text(box,"Remove this nap?",22,600,Design.INK);Design.space(box,12);Design.text(box,"Your other alarms and sleep history stay on this phone.",14,400,Design.MUTED);Design.button(box,"Remove nap",true,()->{synchronized(Scheduler.class){try(Store store=Records.open(this)){Alarm saved=store.alarm(draft.id);if(saved==null||saved.nap==null||!saved.nap.nonce.equals(draft.nap.nonce)||saved.enabled||saved.nap.phase==NapPlan.Phase.CLAIMED){error="This nap changed. Reopen it before removing it.";}else{Naps.cancelJob(this,saved);store.deleteAlarm(saved.id);draft=new Alarm(0);draft.smartWindow=0;if(exactSeconds>0)minutes=20;exactSeconds=0;timerRequest=false;timerMessage="";power=false;powerWindow=15;closeTone();}}}confirm.dismiss();route="list";render();});Design.button(box,"Keep nap",false,confirm::dismiss);confirm.setContentView(box);confirm.show();confirm.getWindow().setBackgroundDrawableResource(android.R.color.transparent);confirm.getWindow().setLayout(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),-2);return confirm;});}
