 private void list(LinearLayout b){RecordUi.header(b,"Multiple naps",this::back);Design.space(b,18);Design.item(b,"calendar","Saved nap profiles","One-date timers or weekly wake alarms",()->startActivity(RecordUi.intent(this,NapProfilesActivity.class)));Design.line(b);Design.space(b,12);List<Alarm> naps;try(Store store=Records.open(this)){naps=store.alarms();}int count=0;for(Alarm a:naps)if(a.nap!=null){count++;LinearLayout row=Design.item(b,"clock",a.label,a.enabled&&a.nap.phase==NapPlan.Phase.PENDING?(a.nap.exactSeconds>0?RecordUi.preciseClock(this,a.nap.projectedDeadline(Naps.clock(this)),ZoneId.systemDefault()):RecordUi.clock(this,a.nap.projectedDeadline(Naps.clock(this)),ZoneId.systemDefault())):a.nap.phase==NapPlan.Phase.CANCELLED?"Cancelled":a.nap.phase==NapPlan.Phase.FINISHED?"Completed":a.nap.phase==NapPlan.Phase.CLAIMED?"Check alarm":"Not running",()->select(a));row.setContentDescription("Open nap "+a.id);Design.line(b);}if(count==0)Design.text(b,"No saved naps",17,500,Design.MUTED);Design.fixedAction(b,"New nap",()->{closeTone();draft=new Alarm(0);draft.smartWindow=0;if(exactSeconds>0)minutes=20;exactSeconds=0;timerRequest=false;timerMessage="";power=false;powerWindow=15;minutes=20;deleteAfter=true;error="";go("");});}
 private void select(Alarm a){closeTone();exactSeconds=0;timerRequest=false;timerMessage="";draft=a;readPlan(a.nap);error="";go("");}
 private void schedule(LinearLayout b){RecordUi.header(b,"Schedule nap",this::back);Design.space(b,22);Design.text(b,"Start date",16,600,Design.INK);if(date.isEmpty())date=Instant.ofEpochMilli(Naps.clock(this).wall()).atZone(ZoneId.systemDefault()).toLocalDate().toString();dateInput=new EditText(this);dateInput.setSingleLine(true);dateInput.setText(date);dateInput.setContentDescription("Nap start date");dateInput.setHint("YYYY-MM-DD");dateInput.setTextSize(18);dateInput.setTypeface(Design.font(this,400));dateInput.setTextColor(Design.INK);Design.pad(dateInput,14,14);dateInput.setBackground(Design.outline(this,Design.CREAM,Design.LINE,12));b.addView(dateInput);Design.space(b,18);Design.item(b,"clock","Start time",Design.clock(this,scheduledMinute),()->{date=dateInput.getText().toString();open(()->SleepPicker.time(this,"Nap start time",scheduledMinute,n->{scheduledMinute=n;render();}));});Design.line(b);Design.item(b,"clock",power?"Latest wake after":"Duration",exactSeconds>0?TimerRequest.duration(exactSeconds):totalMinutes()+" min",null);if(power)Design.text(b,minutes+" min minimum rest + "+powerWindow+" min wake interval",14,500,Design.INK);Design.text(b,ZoneId.systemDefault().getId(),12,400,Design.MUTED);Design.space(b,12);Design.item(b,"info","About scheduled naps",null,()->open(()->SleepPicker.message(this,"Scheduled naps","The saved timer includes your chosen start and duration. It does not start tracking. During a repeated daylight-saving hour the earlier occurrence is used; a missing clock time is rejected. On this boot, changing the phone clock does not change the remaining timer.")));LinearLayout footer=RecordUi.footer(b);issue(footer);Design.button(footer,"Schedule nap",true,()->{try{date=dateInput.getText().toString().trim();LocalDateTime local=LocalDate.parse(date).atTime(scheduledMinute/60,scheduledMinute%60);ZoneId zone=ZoneId.systemDefault();List<ZoneOffset> offsets=zone.getRules().getValidOffsets(local);if(offsets.isEmpty())throw new IllegalArgumentException("That clock time does not exist. Choose a later time.");long selected=local.toInstant(offsets.get(0)).toEpochMilli();if(selected<=Naps.clock(this).wall())throw new IllegalArgumentException("Choose a future start date and time.");Alarm template=Alarm.read(draft.json());template.id=0;template.nap=null;draft=startDraft(template,selected);startAt=0;error="";go("");}catch(RuntimeException failure){error=notice(failure);render();}});}
 private Alarm startDraft(Alarm template,long start){String message=timerRequest&&!timerMessage.isEmpty()?timerMessage:null;return exactSeconds>0?Naps.startSeconds(this,template,exactSeconds,start,deleteAfter,message):Naps.start(this,template,totalMinutes(),start,deleteAfter,power?minutes:0,message);}
 private long durationMillis(){return exactSeconds>0?exactSeconds*1000L:totalMinutes()*60000L;}
 private String remainingLabel(long milliseconds){if(exactSeconds==0||milliseconds>86400000L)return RecordUi.duration(milliseconds);long seconds=(Math.max(0,milliseconds)+999)/1000;return seconds==0?"0 sec":TimerRequest.duration((int)Math.min(86400,seconds));}
 private void editExact(Bundle restored){if(draft==null||pending()||claimed()||!route.isEmpty())return;if(dialog!=null&&dialog.isShowing())return;int initial=exactSeconds>0?exactSeconds:Math.min(86400,totalMinutes()*60);dialog=new ExactTimerPicker(this,initial,restored,seconds->{if(isFinishing()||isDestroyed()||draft==null||pending()||claimed())return;exactSeconds=seconds;minutes=(seconds+59)/60;power=false;draft.smartWindow=0;error="";render();});}
 private int totalMinutes(){return power?Math.addExact(minutes,powerWindow):minutes;}
 private void readPlan(NapPlan p){exactSeconds=p.exactSeconds;if(exactSeconds>0){draft.smartWindow=0;timerRequest=true;timerMessage=TimerRequest.clean(draft.label);}power=p.power();minutes=power?p.minimumRestMinutes:p.minutes;powerWindow=power?p.wakeInterval():15;deleteAfter=p.deleteAfter;}
 private String motionNotice(){return draft.smartWindow==0?"Timer only · wakes at the latest time":Naps.activeTracking.getAsBoolean()?"Movement available · never before minimum rest":"Movement unavailable · latest timer remains";}
 private void powerOptions(LinearLayout b,String title,int[] values,int selected,java.util.function.IntConsumer change){Design.text(b,title,16,600,Design.INK);Design.space(b,8);String[] names=new String[values.length];for(int n=0;n<values.length;n++)names[n]=values[n]+" min";LinearLayout row=RecordUi.segments(b,names,java.util.Arrays.binarySearch(values,selected),n->change.accept(values[n]));for(int n=0;n<values.length;n++)row.getChildAt(n).setContentDescription(title+" "+values[n]+" minutes");}
 private void powerSettings(LinearLayout b){RecordUi.header(b,"Power nap",()->go(""));Design.space(b,18);Design.toggle(b,"Minimum-rest mode","A protected rest interval, then a later chance to wake",power,on->{power=on;if(draft.smartWindow>0)draft.smartWindow=on?powerWindow:5;render();});Design.space(b,16);powerOptions(b,"Minimum rest",new int[]{10,20,30,90},minutes,n->{minutes=n;render();});Design.space(b,18);powerOptions(b,"Later wake interval",new int[]{5,15,30,60},powerWindow,n->{powerWindow=n;if(power&&draft.smartWindow>0)draft.smartWindow=powerWindow;render();});Design.space(b,18);Design.text(b,"Earliest wake after "+minutes+" min · latest after "+(minutes+powerWindow)+" min",16,600,Design.INK);Design.space(b,12);boolean motion=Naps.activeTracking.getAsBoolean();Design.text(b,motion?"Phone movement tracking is active. Smart wake-up can be enabled on the nap screen.":"Movement tracking is unavailable. The latest timer still works; no tracking starts here.",14,400,Design.MUTED);Design.space(b,12);Design.text(b,"Minimum rest is elapsed timer time, not measured sleep. No sleep-stage estimate.",12,400,Design.MUTED);Design.fixedAction(b,"Use nap interval",()->go(""));}
 private void closeTone(){if(tone!=null){tone.close();tone=null;}toneState=null;}
 private AlarmToneScreen tone(){if(tone==null){tone=new AlarmToneScreen(this,draft,toneState,this::render,()->go(""),()->go("gentle"));if(resumed)tone.resume();}return tone;}
 private void gentle(LinearLayout b){
  RecordUi.header(b,"Gentle wake-up",()->go("sound"));Design.space(b,18);
  gentleDuration(b,"sound","Volume ramp",draft.rampSeconds,n->draft.rampSeconds=n,false);
  b.addView(new AlarmRampChart(this,draft),new LinearLayout.LayoutParams(-1,Design.dp(this,220)));Design.space(b,12);Design.line(b);
  gentleDuration(b,"clock","Sound delay",draft.soundDelaySeconds,n->draft.soundDelaySeconds=n,false);Design.line(b);
  Design.toggle(b,"Vibration",null,draft.vibrate,on->{draft.vibrate=on;render();});
  LinearLayout vibration=gentleDuration(b,"vibrate","Vibration starts",draft.vibrationDelaySeconds,n->draft.vibrationDelaySeconds=n,true);RecordUi.enabled(vibration,draft.vibrate);Design.line(b);
  Design.toggle(b,"Screen sunrise","Brighten the alarm screen gradually",draft.sunrise,on->draft.sunrise=on);Design.space(b,10);
  Design.toggle(b,"Flashlight wake-up","Keep the rear light on while ringing",draft.flashlight,on->draft.flashlight=on);Design.space(b,12);
  Design.item(b,"info","About gentle wake-up",null,()->open(()->SleepPicker.message(this,"Gentle wake-up","Sound starts after its delay, then follows the volume ramp. Vibration has its own start time. Screen sunrise brightens only the alarm window. Flashlight availability depends on the camera permission and phone.")));
  Design.fixedAction(b,"Save changes",()->go("sound"));
 }
 private LinearLayout gentleDuration(LinearLayout body,String icon,String title,int selected,java.util.function.IntConsumer use,boolean fromStart){
  String value=selected==0?(fromStart?"From start":"Off"):selected<60?selected+" sec":selected/60+" min";
  return Design.item(body,icon,title,value,()->openGentleDuration(title,selected,use,fromStart));
 }
 private void openGentleDuration(String title,int selected,java.util.function.IntConsumer use,boolean fromStart){
  if(draft==null||pending()||claimed())return;
  open(()->{int[] choices=AlarmWakeTimes.options();String[] labels=new String[choices.length];int checked=-1;
   for(int n=0;n<choices.length;n++){int seconds=choices[n];labels[n]=seconds==0?(fromStart?"From start":"Off"):seconds<60?seconds+" sec":seconds/60+" min";if(seconds==selected)checked=n;}
   return SleepPicker.choices(this,title,labels,checked,index->{if(draft==null||pending()||claimed())return;use.accept(choices[index]);render();});
  });
 }
 private void restoreGentlePicker(){
  if(picker==null||draft==null||!route.equals("gentle")||pending()||claimed()){picker=null;return;}
  switch(picker.getString("sleepPickerTitle","")){
   case "Volume ramp"->openGentleDuration("Volume ramp",draft.rampSeconds,n->draft.rampSeconds=n,false);
   case "Sound delay"->openGentleDuration("Sound delay",draft.soundDelaySeconds,n->draft.soundDelaySeconds=n,false);
   case "Vibration starts"->{if(draft.vibrate)openGentleDuration("Vibration starts",draft.vibrationDelaySeconds,n->draft.vibrationDelaySeconds=n,true);else picker=null;}
   default->picker=null;
  }
 }

 private void go(String next){if(preview!=null)preview.stop();if(tone!=null&&!next.equals("sound")){tone.stop();toneState=tone.save();}route=next;render();}
 private void open(java.util.function.Supplier<Dialog> create){if(dialog!=null&&dialog.isShowing())return;dialog=create.get();if(picker!=null&&dialog instanceof SleepPicker.StateDialog){dialog.onRestoreInstanceState(picker);picker=null;}}
 private void back(){if(route.isEmpty())finish();else go(route.equals("gentle")?"sound":"");}
 private static String notice(RuntimeException e){return e.getMessage()==null?"Your nap could not be saved. Try again.":e.getMessage();}
 @Override protected void onResume(){super.onResume();resumed=true;if(draft!=null&&pending())try{String denied=Naps.ports.create(getApplicationContext()).access();if(!denied.isEmpty()){Naps.reconcile(this,draft.id);reload();render();}}catch(RuntimeException failure){error=notice(failure);render();}if(preview!=null)preview.visible(hasWindowFocus());if(tone!=null)tone.resume();handler.post(tick);}
 @Override protected void onPause(){resumed=false;handler.removeCallbacks(tick);if(preview!=null)preview.visible(false);if(tone!=null)tone.pause();super.onPause();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);if(preview!=null)preview.visible(focus&&resumed);if(tone!=null)tone.focus(focus&&route.equals("sound"));}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==AlarmToneImport.REQUEST&&tone!=null)tone.result(result,data);}
 @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);if(draft==null)return;if(dateInput!=null)date=dateInput.getText().toString();b.putString("draft",draft.json().toString());b.putString("route",route);b.putString("error",error);b.putString("date",date);b.putInt("minute",scheduledMinute);b.putInt("minutes",minutes);b.putInt("exactSeconds",exactSeconds);if(dialog instanceof ExactTimerPicker exact&&dialog.isShowing())b.putBundle("exactPicker",exact.draft());b.putBoolean("timerRequest",timerRequest);b.putString("timerMessage",timerMessage);b.putBoolean("power",power);b.putInt("powerWindow",powerWindow);b.putBoolean("delete",deleteAfter);b.putLong("startAt",startAt);if(tone!=null)toneState=tone.save();b.putBundle("tone",toneState);if(dialog!=null&&dialog.isShowing()&&dialog instanceof SleepPicker.StateDialog)b.putBundle("picker",dialog.onSaveInstanceState());}
 View captureView(){return dialog!=null&&dialog.isShowing()?dialog.getWindow().getDecorView():getWindow().getDecorView();}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(dialog!=null)dialog.dismiss();if(tone!=null)tone.close();if(preview!=null)preview.close();worker.shutdown();super.onDestroy();}
